<template>
  <div class="table-container">
    <div class="charter-list">
      <div class="card-container">
        <div v-for="({ key: charterName, value: songList }, index) in sortedCardList" :key="charterName" class="charter-group">
          <div class="charter-title">{{ charterName }}</div>
          <div class="card-grid" :style="getGridStyle()">
            <div
              v-for="(item, idx) in getGroupSortedCards(songList)"
              :key="idx"
              class="chart-card"
            >
              <div class="card-cover">
                <img :src="item.songData.cover" :alt="item.songData.name" class="cover-img" />
                <div class="diff-badge" :style="{ backgroundColor: item.diffData.color }">
                  {{ item.diffKey }} Lv.{{ item.diffData.lvl }}
                </div>
              </div>
              <div class="card-info">
                <div class="info-title">{{ item.diffData.charter }}</div>
                <div class="info-charter">{{ item.diffData.tcharter }}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, onMounted, ref, defineProps } from 'vue';
import charterGet from './components/charterGet.vue';

const charterList = ref(null)

onMounted(async () => {
  try {
    const charterData = await charterGet.methods.getCharter('/files/infos/charters.json')
    charterList.value = charterData
  } catch (error) {
    console.error('谱师列表加载失败：', error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 2
  },
  gap: {
    type: Number,
    default: 0.14
  },
})

const getGridStyle = () => {
  return {
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
}

const sortedCardList = computed(() => {
  if(!charterList.value) return []
  return Object.entries(charterList.value).map(([key, value]) => ({ key, value }));
});

const getGroupSortedCards = (songList) => {
  const items = []
  Object.values(songList).forEach((songData) => {
    const { name, cover, ...difficulties } = songData
    Object.entries(difficulties).forEach(([diffKey, diffData]) => {
      items.push({ songData, diffKey, diffData })
    })
  })
  return items.sort((a, b) => {
    const qa = String(a.diffData.lvl).includes("?")
    const qb = String(b.diffData.lvl).includes("?")
    if (qa && !qb) return -1
    if (!qa && qb) return 1
    const na = Number(a.diffData.lvl) || 0
    const nb = Number(b.diffData.lvl) || 0
    return nb - na
  })
}
</script>

<style scoped>
.card-container {
  width: 100%;
}

.charter-group {
  margin-bottom: 0.45rem;
}

.charter-title {
  font-size: 0.22rem;
  font-weight: bold;
  color: #ffffff;
  background: #2a2d2f;
  padding: 0.12rem 0.16rem;
  margin-bottom: 0.16rem;
  text-align: center;
  user-select: none;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(var(--column-count), 1fr);
  gap: var(--gap-rem);
  width: 100%;
}

.chart-card {
  display: flex;
  height: 1.5rem;
  background-color: #212426;
  overflow: hidden;
  color: #ffffff;
  box-shadow: 0 0.01rem 0.04rem rgba(0, 0, 0, 0.2);
  box-sizing: border-box;
}

.card-cover {
  aspect-ratio: 256 / 135;
  position: relative;
  flex-shrink: 0;
  user-select: none;
}

.cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.diff-badge {
  position: absolute;
  right: 0.08rem;
  bottom: 0.08rem;
  padding: 0.08rem 0.12rem;
  font-size: 0.13rem;
  color: #fff;
  min-width: 0.8rem;
  text-align: center;
  user-select: none;
}

.card-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 0.12rem;
  font-size: 0.18rem;
  text-align: center;
}

.info-title {
  font-weight: bold;
  font-size: 0.22rem;
  margin-bottom: 0.04rem;
}

.info-charter {
  line-height: 1.4;
  font-size: 0.16rem;
  word-break: break-all;
}

.table-container {
  width: 100%;
}

.charter-list {
  margin-top: 0.2rem;
}

.card-grid > * {
  width: 100%;
  box-sizing: border-box;
}
</style>